test('without a headline the block says the reports hold the figures, in each locale', () => {
  assert.match(
    performanceBlock('en', []),
    /No report quotes its figures here yet/,
  );
  assert.match(performanceBlock('zh', []), /尚无报告在此引用其数字/);
});

test('a headline is a table of its figures, under its environment, report and builds, each row with its CPU and build', () => {
  const block = performanceBlock('en', [HEADLINE]);
  assert.match(
    block,
    /^<!-- Generated by \.github\/scripts\/docs-performance\.mjs/,
  );
  assert.match(
    block,
    /\*\*Apple M5 Max, 18 cores, 64 GB, one host\*\*: \[m5max-snapshot\]\(https:\/\/github\.com\/Ahoo-Wang\/Wow\/blob\/main\/test\/benchmarks\/results\/reports\/m5max-snapshot\.md\), build `d9b0781205`\./,
  );
  assert.ok(
    block.includes(
      '| PostgreSQL | one | E1 | uniform | ≥ 37,713.6/s, at 4,096 clients | 23,030.1/s, at 1,024 clients, p99 74.8 ms | Apple M5 Max, JDK 25.0.5+8, `d9b0781205` |',
    ),
  );
  assert.ok(
    block.includes(
      '| MongoDB | 3 | E3 | one hot account | 5,380.1/s, at 1,024 clients | – | Apple M5 Max, JDK 25.0.5+8, `d9b0781205` |',
    ),
  );
  assert.equal(
    block
      .split('\n')
      .filter(
        line =>
          line.startsWith('| ') &&
          !line.startsWith('| Store') &&
          !line.startsWith('| ---'),
      ).length,
    2,
  );
  assert.ok(
    performanceBlock('zh', [HEADLINE]).includes(
      '| MongoDB | 3 | E3 | 单个热点账户 | 5,380.1/s，1,024 个客户端 | – | Apple M5 Max，JDK 25.0.5+8，`d9b0781205` |',
    ),
  );
});

test("an Actions headline is its sustainable rates beside the closed-loop saturation, named by the runner's CPU", () => {
  const block = performanceBlock('en', [ACTIONS]);
  assert.ok(
    block.includes(
      '| PostgreSQL | one | E1 | uniform | 4,912.5/s, closed loop | 2,609.8/s, open loop, p99 160.8 ms | EPYC 9V45, JDK 25.0.5+8, `d8284109df` |',
    ),
  );
  // A unit cost is no row of this table.
  assert.ok(!block.includes('a7c372ad3e'));
  assert.match(block, /build `d8284109df`\./);
});

test("the CPU names are a reader's", () => {
  assert.equal(cpuName('AMD EPYC 7763 64-Core Processor'), 'EPYC 7763');
  assert.equal(cpuName('Apple M5 Max, 18 cores, 64 GB'), 'Apple M5 Max');
  assert.equal(cpuName('Intel(R) Xeon(R) 6975P-C'), 'Xeon 6975P-C');
  assert.equal(cpuName('INTEL(R) XEON(R) PLATINUM 8573C'), 'Xeon 8573C');
  assert.equal(
    cpuName('Intel(R) Xeon(R) Platinum 8370C CPU @ 2.80GHz'),
    'Xeon 8370C',
  );
});

test('a headline that lacks a field the table needs is refused, naming it', () => {
  assert.throws(
    () => checkedHeadline({ ...HEADLINE, environment: undefined }, 'h.json'),
    /h\.json lacks environment/,
  );
  assert.throws(
    () =>
      checkedHeadline(
        {
          ...HEADLINE,
          figures: [{ id: 'x', kind: 'sweep', commit: 'c', cpu: 'p' }],
        },
        'h.json',
      ),
    /figure 1 lacks jdk, source/,
  );
  assert.throws(
    () =>
      checkedHeadline(
        {
          ...HEADLINE,
          figures: [{ ...HEADLINE.figures[0], store: 'redis' }],
        },
        'h.json',
      ),
    /sweep\.postgres\.1\.e1-sweep lacks a known store \(postgres, mongo\)/,
  );
});

test('a named block replaces what is between its markers and nothing else', () => {
  const text = `# Performance\n\nBefore.\n\n${BEGIN}\nstale\n${END}\n\nAfter.\n`;
  assert.equal(
    withFigures(text, 'en', [HEADLINE], 'p.md'),
    `# Performance\n\nBefore.\n\n${BEGIN}\n${performanceBlock('en', [HEADLINE])}\n${END}\n\nAfter.\n`,
  );
  // Two blocks on one page are each written.
  const twice = withFigures(
    `${BEGIN}\n${END}\n\nBetween.\n\n${BEGIN}\nold\n${END}\n`,
    'zh',
    [HEADLINE],
    'p.md',
  );
  assert.equal(twice.split(performanceBlock('zh', [HEADLINE])).length, 3);
  assert.ok(twice.includes(`${END}\n\nBetween.\n\n${BEGIN}`));
  // A page with neither is left as it is.
  assert.equal(withFigures('# None\n', 'en', [], 'p.md'), '# None\n');
});

test('a block of no known name, or a marker without its pair, is refused, naming the page', () => {
  assert.throws(
    () => withFigures(`${begin('curves')}\n${END}\n`, 'en', [], 'p.md'),
    /p\.md: no block is named curves \(snapshots\)/,
  );
  for (const text of [
    `${BEGIN}\nno end\n`,
    `${BEGIN}\n${BEGIN}\n${END}\n`,
    `${END}\n${BEGIN}\n`,
  ]) {
    assert.throws(
      () => withFigures(text, 'en', [], 'p.md'),
      /p\.md: <!-- performance:begin snapshots --> must be followed by <!-- performance:end -->/,
    );
  }
  assert.throws(
    () => withFigures(`${BEGIN}\n${END}\n${END}\n`, 'en', [], 'p.md'),
    /p\.md: <!-- performance:end --> without its/,
  );
});

test("an inline span is its figure's number, a rate, a time or a count, rewritten when it drifts", () => {
  const text = [
    'PostgreSQL sustains <!-- perf:actions-snapshot/sustainable.postgres.E1:value -->2,000/s<!-- /perf --> at',
    'p99 <!-- perf:actions-snapshot/sustainable.postgres.E1:p99Ms -->?<!-- /perf -->, and one M5 Max node',
    '<!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:sustainable.value --><!-- /perf --> with',
    '<!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:sustainable.clients -->1<!-- /perf --> clients.',
  ].join('\n');
  assert.equal(
    withFigures(text, 'zh', [HEADLINE, ACTIONS], 'p.md'),
    [
      'PostgreSQL sustains <!-- perf:actions-snapshot/sustainable.postgres.E1:value -->2,609.8/s<!-- /perf --> at',
      'p99 <!-- perf:actions-snapshot/sustainable.postgres.E1:p99Ms -->160.8 ms<!-- /perf -->, and one M5 Max node',
      '<!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:sustainable.value -->23,030.1/s<!-- /perf --> with',
      '<!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:sustainable.clients -->1,024<!-- /perf --> clients.',
    ].join('\n'),
  );
  assert.equal(spanText('saturation', 4912.5), '4,912.5/s');
  // A peak the sweep's last step reached is a lower bound, and says so as the tables do.
  assert.equal(
    withFigures(
      '<!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:value --><!-- /perf -->',
      'en',
      [HEADLINE],
      'p.md',
    ),
    '<!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:value -->≥ 37,713.6/s<!-- /perf -->',
  );
  assert.equal(spanText('p50Ms', 4.7), '4.7 ms');
});

test('a span whose report, figure or number the headlines do not hold is refused, naming it', () => {
  const span = ref => `x <!-- perf:${ref} -->1<!-- /perf -->`;
  assert.throws(
    () =>
      withFigures(span('actions-axon/peak.e1:value'), 'en', [ACTIONS], 'p.md'),
    /p\.md: perf:actions-axon\/peak\.e1:value names no quoted report \(actions-snapshot\)/,
  );
  assert.throws(
    () =>
      withFigures(
        span('actions-snapshot/sustainable.mongo.E1:value'),
        'en',
        [ACTIONS],
        'p.md',
      ),
    /actions-snapshot has no figure sustainable\.mongo\.E1/,
  );
  // A field the figure lacks, and one that is not a number (the sustainable step a sweep did not find).
  for (const ref of [
    'actions-snapshot/sustainable.postgres.E1:p50Ms',
    'm5max-snapshot/sweep.mongo.3.e3-sweep:sustainable.value',
    'actions-snapshot/sustainable.postgres.E1:store',
  ]) {
    assert.throws(
      () => withFigures(span(ref), 'en', [HEADLINE, ACTIONS], 'p.md'),
      /the figure has no number there/,
    );
  }
});

test("the pages take the headlines of the reports present in the tree, from their data, in the page's order", () => {
  const root = mkdtempSync(join(tmpdir(), 'docs-performance-'));
  for (const path of Object.values(PAGES)) {
    mkdirSync(join(root, dirname(path)), { recursive: true });
    writeFileSync(join(root, path), `# Page\n\n${BEGIN}\n${END}\n`);
  }
  const report = join(root, dirname(HEADLINES[1]));
  mkdirSync(report, { recursive: true });
  writeFileSync(
    join(report, 'environment.txt'),
    'commit: d9b0781205aa5749bf7e3941dfcbb622c2eaac36\n',
  );
  writeFileSync(
    join(report, 'summary.json'),
    JSON.stringify({
      measurements: {
        '1-S-postgres/e1-sweep': {
          kind: 'sweep',
          scenario: 'E1',
          keys: 'uniform',
          nodes: 1,
          backend: 'postgres',
          peak: { throughput: 37713.6, clients: 4096, lowerBound: true },
          sustainable: null,
          steps: [],
        },
      },
    }),
  );
  // Another page of the documentation that quotes a figure inline is written too; one that quotes none is not.
  const guide = 'documentation/docs/en/guide/why.md';
  mkdirSync(join(root, dirname(guide)), { recursive: true });
  writeFileSync(
    join(root, guide),
    'One node: <!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:value --><!-- /perf -->.\n',
  );
  writeFileSync(join(root, dirname(guide), 'plain.md'), '# Plain\n');
  const pages = performancePages(root);
  assert.deepEqual(Object.keys(pages), [
    HEADLINES[1],
    PAGES.en,
    guide,
    PAGES.zh,
  ]);
  assert.equal(
    pages[guide],
    'One node: <!-- perf:m5max-snapshot/sweep.postgres.1.e1-sweep:value -->≥ 37,713.6/s<!-- /perf -->.\n',
  );
  assert.match(pages[HEADLINES[1]], /"schema": "wow-headline\/1"/);
  assert.ok(pages[PAGES.en].includes('[m5max-snapshot]'));
  assert.ok(pages[PAGES.en].includes('≥ 37,713.6/s, at 4,096 clients'));
  assert.ok(!pages[PAGES.en].includes('actions-snapshot'));
});

test('a report with no row the table quotes is left out of the block', () => {
  const empty = { ...HEADLINE, figures: [] };
  assert.match(
    performanceBlock('en', [empty]),
    /No report quotes its figures here yet/,
  );
});

test('the block says once that each figure is from the build, JDK and runner its row names, in each locale', () => {
  const en = performanceBlock('en', [HEADLINE]);
  assert.equal(
    en.match(
      /Each figure is from the build, the JDK and the runner its row names\./g,
    ).length,
    1,
  );
  assert.doesNotMatch(en, /beta\.3/);
  assert.match(
    performanceBlock('zh', [HEADLINE]),
    /每个数字都来自其所在行注明的构建、JDK 与机器。/,
  );
});

test('a report whose rows name more than one CPU model says once that they do not compare the stores, in each locale', () => {
  const on = (cpu, store) => ({
    ...HEADLINE.figures[0],
    id: `sustainable.${store}.E1`,
    kind: 'sustainable',
    store,
    cpu,
  });
  const mixed = {
    ...HEADLINE,
    figures: [
      on('Intel(R) Xeon(R) 6975P-C', 'mongo'),
      on('AMD EPYC 7763 64-Core Processor', 'postgres'),
    ],
  };
  const en = performanceBlock('en', [mixed]);
  assert.equal(
    en.match(
      /These rows ran on 2 CPU models, which each row names: two rows on different models do not compare the stores, nor the scenarios\./g,
    ).length,
    1,
  );
  assert.match(
    performanceBlock('zh', [mixed]),
    /这些行来自 2 种 CPU 型号，每行注明了自己的型号：型号不同的两行既不能用来比较存储，也不能用来比较场景。/,
  );
  const one = {
    ...mixed,
    figures: [
      on('AMD EPYC 7763 64-Core Processor', 'mongo'),
      on('AMD EPYC 7763 64-Core Processor', 'postgres'),
    ],
  };
  assert.doesNotMatch(performanceBlock('en', [one]), /CPU models/);
  assert.doesNotMatch(performanceBlock('en', [HEADLINE]), /CPU models/);
});

